#!/usr/bin/env bash
# DURUM_READONLY_V1 deploy — nokta durumu seçicilerini salt-okunur yap (ERP'den otomatik). Rule 5. Idempotent.
set -e
cd /opt/krb-assessment
if [ -f shells/saha.js ]; then SAHA=shells/saha.js; else SAHA=$(find . -maxdepth 3 -name saha.js -not -path '*/backups/*' -not -path '*/node_modules/*'|head -1); fi
[ -f "$SAHA" ] || { echo "HATA: saha.js yok"; exit 1; }
cp "$SAHA" "$SAHA.bak.$(date +%s)"
printf '%s' '' | base64 -d > /tmp/durum_readonly.py
SDIR=$(dirname "$SAHA"); cp /tmp/durum_readonly.py "$SDIR/durum_readonly.py"
( cd "$SDIR" && python3 durum_readonly.py ) && rm -f "$SDIR/durum_readonly.py"
node --check "$SAHA" && echo SAHA_OK
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== verify (düzenlenebilir durum seçici=0, marker>=1) =="
docker exec krb-assessment sh -c "grep -c 'id=\"pt-durum\"\|id=\"zf-durum\"\|id=\"md-durum-sec\"\|md-durum-kaydet' /app/shells/saha.js" || true
docker exec krb-assessment sh -c "grep -c DURUM_READONLY_V1 /app/shells/saha.js" || true
echo "== DONE =="
